[Fact]
public async Task Get_account_returns_balance()
{
    var pact = Pact.V4("mobile-bff", "accounts-api", new PactConfig { PactDir = "../../pacts" }).WithHttpInteractions();
    pact.UponReceiving("a request for an existing account")
        .Given("account 42 exists")
        .WithRequest(HttpMethod.Get, "/accounts/42")
        .WillRespond()
        .WithStatus(HttpStatusCode.OK)
        .WithJsonBody(new { id = Match.Type("42"), currency = Match.Regex("GBP", "^[A-Z]{3}$"), balance = Match.Decimal(120.50m) });

    await pact.VerifyAsync(async ctx =>
    {
        var client = new AccountsClient(new HttpClient { BaseAddress = ctx.MockServerUri });
        var acc = await client.GetAsync("42");
        Assert.Equal("GBP", acc.Currency);
    });
}
// Deploy gate: pact-broker can-i-deploy --pacticipant mobile-bff --version $GIT_SHA --to-environment production
