-- Backfill job: resumable, throttled batches by key range with checkpoint
DECLARE @from BIGINT = (SELECT LastKey FROM ops.BackfillCheckpoint WHERE Name = 'tx-rekey');
DECLARE @batch INT = 20000, @rows INT = 1;
WHILE @rows > 0
BEGIN
    BEGIN TRAN;
        INSERT INTO ledger.Transactions_v2 WITH (TABLOCK) (AccountId, BookedOn, TxId, Amount, Currency, Narrative)
        SELECT t.AccountId, t.BookedOn, t.TxId, t.Amount, t.Currency, t.Narrative
        FROM ledger.Transactions t
        WHERE t.TxId > @from AND t.TxId <= @from + @batch
          AND NOT EXISTS (SELECT 1 FROM ledger.Transactions_v2 n WHERE n.TxId = t.TxId);    -- dual-written rows skipped
        SET @rows = @@ROWCOUNT;
        SET @from = @from + @batch;
        UPDATE ops.BackfillCheckpoint SET LastKey = @from, UpdatedAt = SYSUTCDATETIME() WHERE Name = 'tx-rekey';
    COMMIT;
    IF (SELECT MAX(secondary_lag_seconds) FROM sys.dm_hadr_database_replica_states) > 30 WAITFOR DELAY '00:00:30';   -- protect replicas
    ELSE WAITFOR DELAY '00:00:00.200';
END;
